

























































































import { listProductCategoryByType } from '@/api/product-category'
import { getBundlePage, enableOrDisableBundle, deleteBundle } from '@/api/bundle'

export default {
  //模型数据
  data() {
    return {
      name: '', //组合商品名称，对应上面的输入框
      page: 1, //页码
      pageSize: 10, //每页记录数
      total: 0, //总记录数
      records: [], //当前页要展示的数据集合
      options: [],
      categoryId: '', //分类id
      statusArr:[
        {
          value: '0',
          label: '已下架'
        },
        {
          value: '1',
          label: '已上架'
        }
      ],
      status: '', //售卖状态,
      multipleSelection: ''//当前表格选中的多个元素
    }
  },
  created() {
    listProductCategoryByType({type: 2}).then(res => {
      if(res.data.code === 1) {
        this.options = res.data.data
      }
    })

    //页面加载完成后查询组合商品分页数据
    this.pageQuery()
  },
  methods: {
    //分页查询
    pageQuery() {
      //封装分页查询参数
      const params = {
        page: this.page,
        pageSize: this.pageSize,
        name: this.name,
        status: this.status,
        categoryId: this.categoryId
      }

      getBundlePage(params).then(res => {
        if(res.data.code === 1){
          this.total = res.data.data.total
          this.records = res.data.data.records
        }
      })
    },
    handleSizeChange(pageSize) {
      this.pageSize = pageSize
      this.pageQuery()
    },
    handleCurrentChange(page) {
      this.page = page
      this.pageQuery()
    },
    handleEdit(row) {
      this.$router.push(`/bundle/add?id=${row.id}`)
    },
    //组合商品上架/下架操作
    handleStartOrStop(row) {
      const p = {
        id: row.id,
        status: !row.status ? 1: 0
      }

      this.$confirm('确认调整当前组合商品的上架状态, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          enableOrDisableBundle(p).then(res => {
            if(res.data.code === 1) {
              this.$message.success('组合商品状态修改成功！')
              this.pageQuery()
            }
          })
        })
    },
    //删除组合商品
    handleDelete(type: string,id: string) {
      this.$confirm('确认删除当前指定的组合商品, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          let param = ''
          if(type == 'B'){ //批量删除
            const arr = []
            this.multipleSelection.forEach(element => { //1,2,3
              arr.push(element.id)
            })
            param = arr.join(',')
          }else{ //单一删除
            param = id
          }

          deleteBundle(param).then(res => {
            if(res.data.code === 1){
              this.$message.success('删除成功！')
              this.pageQuery()
            }else{
              this.$message.error(res.data.msg)
            }
          })
        })
    },
    handleSelectionChange(val) {
      this.multipleSelection = val
      // console.log('当前表格勾选了几项：' + val.length)
      // val.forEach(element => {
      //   console.log('id=' + element.id)
      // })
    }
  }
}
